//! HTTP routing for the kvhttp API.

use std::sync::Arc;

use axum::Router;
use axum::body::Bytes;
use axum::extract::{DefaultBodyLimit, State};
use axum::http::{HeaderValue, Method, StatusCode, Uri, header};
use axum::response::{IntoResponse, Response};

use crate::store::Store;

/// Largest accepted request body: 1 MiB values plus generous headroom.
const MAX_BODY: usize = 8 * 1024 * 1024;

const ALLOW_COLLECTION: &str = "GET";
const ALLOW_ITEM: &str = "GET, PUT, DELETE";

/// Builds the application router backed by `store`.
pub fn router(store: Arc<Store>) -> Router {
    Router::new()
        .fallback(dispatch)
        .layer(DefaultBodyLimit::max(MAX_BODY))
        .with_state(store)
}

/// Returns `true` if `key` matches `[A-Za-z0-9_-]{1,64}`.
fn is_valid_key(key: &str) -> bool {
    (1..=64).contains(&key.len())
        && key
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}

async fn dispatch(
    State(store): State<Arc<Store>>,
    method: Method,
    uri: Uri,
    body: Bytes,
) -> Response {
    match uri.path() {
        "/health" => health(&method),
        "/kv" => list_keys(&store, &method),
        path => match path.strip_prefix("/kv/") {
            Some(key) => item(&store, &method, key, body),
            None => StatusCode::NOT_FOUND.into_response(),
        },
    }
}

fn method_not_allowed(allowed: &'static str) -> Response {
    (
        StatusCode::METHOD_NOT_ALLOWED,
        [(header::ALLOW, HeaderValue::from_static(allowed))],
    )
        .into_response()
}

fn health(method: &Method) -> Response {
    if method == Method::GET {
        (StatusCode::OK, "ok").into_response()
    } else {
        method_not_allowed(ALLOW_COLLECTION)
    }
}

fn list_keys(store: &Store, method: &Method) -> Response {
    if method != Method::GET {
        return method_not_allowed(ALLOW_COLLECTION);
    }
    let json = serde_json::to_vec(&store.keys()).expect("a list of strings always serializes");
    (
        StatusCode::OK,
        [(header::CONTENT_TYPE, HeaderValue::from_static("application/json"))],
        json,
    )
        .into_response()
}

fn item(store: &Store, method: &Method, key: &str, body: Bytes) -> Response {
    if !is_valid_key(key) {
        return StatusCode::BAD_REQUEST.into_response();
    }
    match *method {
        Method::GET => match store.get(key) {
            Some(value) => (
                StatusCode::OK,
                [(
                    header::CONTENT_TYPE,
                    HeaderValue::from_static("application/octet-stream"),
                )],
                value,
            )
                .into_response(),
            None => StatusCode::NOT_FOUND.into_response(),
        },
        Method::PUT => {
            if store.put(key, body) {
                StatusCode::CREATED.into_response()
            } else {
                StatusCode::OK.into_response()
            }
        }
        Method::DELETE => {
            if store.delete(key) {
                StatusCode::NO_CONTENT.into_response()
            } else {
                StatusCode::NOT_FOUND.into_response()
            }
        }
        _ => method_not_allowed(ALLOW_ITEM),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn key_validation() {
        assert!(is_valid_key("a"));
        assert!(is_valid_key("A-z_09"));
        assert!(is_valid_key(&"a".repeat(64)));
        assert!(!is_valid_key(""));
        assert!(!is_valid_key(&"a".repeat(65)));
        assert!(!is_valid_key("a/b"));
        assert!(!is_valid_key("bad.key"));
        assert!(!is_valid_key("é"));
    }
}

//! Entry point: `app <port>` serves the key-value API on 127.0.0.1.

mod handler;
mod store;

use std::net::{Ipv4Addr, SocketAddr};
use std::process::ExitCode;
use std::sync::Arc;

use tokio::net::TcpListener;

use crate::store::Store;

fn parse_port(arg: Option<String>) -> Option<u16> {
    arg?.parse().ok().filter(|&port| port != 0)
}

#[tokio::main]
async fn main() -> ExitCode {
    let Some(port) = parse_port(std::env::args().nth(1)) else {
        eprintln!("usage: app <port>");
        return ExitCode::from(2);
    };

    let addr = SocketAddr::from((Ipv4Addr::LOCALHOST, port));
    let listener = match TcpListener::bind(addr).await {
        Ok(listener) => listener,
        Err(err) => {
            eprintln!("failed to bind {addr}: {err}");
            return ExitCode::FAILURE;
        }
    };
    println!("kvhttp listening on {addr}");

    let app = handler::router(Arc::new(Store::new()));
    if let Err(err) = axum::serve(listener, app).await {
        eprintln!("server error: {err}");
        return ExitCode::FAILURE;
    }
    ExitCode::SUCCESS
}

//! In-memory key-value store. Keys are kept sorted so listing is cheap.

use std::collections::BTreeMap;
use std::sync::{PoisonError, RwLock};

use bytes::Bytes;

/// A thread-safe, sorted, in-memory map from keys to byte values.
#[derive(Debug, Default)]
pub struct Store {
    entries: RwLock<BTreeMap<String, Bytes>>,
}

impl Store {
    /// Returns a new, empty store.
    pub fn new() -> Self {
        Self::default()
    }

    /// Stores `value` under `key`. Returns `true` if the key was new.
    pub fn put(&self, key: &str, value: Bytes) -> bool {
        let mut entries = self.entries.write().unwrap_or_else(PoisonError::into_inner);
        entries.insert(key.to_owned(), value).is_none()
    }

    /// Returns the value stored under `key`, if any.
    pub fn get(&self, key: &str) -> Option<Bytes> {
        let entries = self.entries.read().unwrap_or_else(PoisonError::into_inner);
        entries.get(key).cloned()
    }

    /// Removes `key`. Returns `true` if it was present.
    pub fn delete(&self, key: &str) -> bool {
        let mut entries = self.entries.write().unwrap_or_else(PoisonError::into_inner);
        entries.remove(key).is_some()
    }

    /// Returns every key in ascending order.
    pub fn keys(&self) -> Vec<String> {
        let entries = self.entries.read().unwrap_or_else(PoisonError::into_inner);
        entries.keys().cloned().collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn put_get_delete() {
        let store = Store::new();
        assert!(store.put("a", Bytes::from_static(b"1")));
        assert!(!store.put("a", Bytes::from_static(b"2")));
        assert_eq!(store.get("a").as_deref(), Some(&b"2"[..]));
        assert!(store.delete("a"));
        assert!(!store.delete("a"));
        assert_eq!(store.get("a"), None);
    }

    #[test]
    fn keys_are_sorted() {
        let store = Store::new();
        for k in ["b", "a", "c"] {
            store.put(k, Bytes::new());
        }
        assert_eq!(store.keys(), ["a", "b", "c"]);
    }
}
